import java.util.*;

class Solution {
  public List<List<Integer>> findSubsequences(int[] nums) {
    List<List<Integer>> ans = new ArrayList<>();
    build(nums, 0, new ArrayList<>(), ans);
    return ans;
  }

  private void build(int[] nums, int start, List<Integer> cur, List<List<Integer>> ans) {
    if (cur.size() >= 2) ans.add(new ArrayList<>(cur));
    Set<Integer> usedHere = new HashSet<>(); // the same value at one depth gives duplicate sequences
    for (int i = start; i < nums.length; i++) {
      if ((!cur.isEmpty() && nums[i] < cur.get(cur.size() - 1)) || !usedHere.add(nums[i])) continue;
      cur.add(nums[i]);
      build(nums, i + 1, cur, ans);
      cur.remove(cur.size() - 1);
    }
  }
}
